import os, io, base64
from PIL import Image
_R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'blender', 'renders')
def _img(n):
    """Icono = render de Blender (blender/renders/<n>.png) convertido a JPEG 256px embebido."""
    buf = io.BytesIO(); Image.open(os.path.join(_R, n + '.png')).convert('RGB').resize((256, 256)).save(buf, 'JPEG', quality=84, optimize=True)
    return f'<image href="data:image/jpeg;base64,{base64.b64encode(buf.getvalue()).decode()}" width="64" height="64" preserveAspectRatio="xMidYMid slice"/>'
